describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            10.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 10000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", undefined, 3)];
      expect(calc.computeShippingCents(lines, 10000)).toBe(0);
    });

    it("selects first bracket matching weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 250, 1)]; // 250g ≤ 500
      expect(calc.computeShippingCents(lines, 10000)).toBe(300);
    });

    it("selects exact boundary bracket", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 500, 1)]; // exactly 500g
      expect(calc.computeShippingCents(lines, 10000)).toBe(300);
    });

    it("moves to next bracket when exceeding boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 501, 1)]; // 501g > 500, ≤ 1000
      expect(calc.computeShippingCents(lines, 10000)).toBe(500);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2500);
      const lines = [makeLine("a", 3000, 2)]; // 6000g > 5000
      expect(calc.computeShippingCents(lines, 10000)).toBe(2500);
    });

    it("uses heaviest bracket cost as default overflow", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 3000, 2)]; // 6000g > 5000
      expect(calc.computeShippingCents(lines, 10000)).toBe(1200);
    });

    it("handles unsorted bracket input (sorts internally)", () => {
      const unsorted = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      const lines = [makeLine("a", 700, 1)]; // 700g ≤ 1000
      expect(calc.computeShippingCents(lines, 10000)).toBe(500);
    });

    it("multiplies weight by quantity", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 300, 2)]; // 600g > 500, ≤ 1000
      expect(calc.computeShippingCents(lines, 10000)).toBe(500);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart — line management", () => {
  it("add creates a new line", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add merges quantity for same product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add throws for non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("add throws for negative unitPriceCents", () => {
    const cart = new Cart();
    const badProduct: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
  });

  it("remove returns true and removes existing product", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(productA, 5);
    cart.updateQuantity("a", 3);
    expect(cart.itemCount).toBe(3);
  });

  it("updateQuantity with 0 removes the line", () => {
    const cart = new Cart();
    cart.add(productA, 5);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("xxx", 5)).toThrow("not in the cart");
  });

  it("updateQuantity throws for negative quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity throws for non-integer quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productB, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const snap = cart.snapshot();
    // mutating snapshot does not affect cart
    (snap as any)[0].quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart — pricing pipeline", () => {
  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("subtotal = sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2000
    expect(cart.totals().subtotalCents).toBe(4000);
  });

  it("discount is applied on subtotal, clamped to [0, subtotal]", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(productA, 1); // subtotal 1000
    const t = cart.totals();
    expect(t.discountCents).toBe(500);
    expect(mockDiscount.computeDiscountCents).toHaveBeenCalledWith(1000);
  });

  it("clamps over-subtotal discount to subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9999),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(productA, 1); // subtotal 1000
    expect(cart.totals().discountCents).toBe(1000);
  });

  it("clamps negative discount to 0", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(productA, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("tax is computed on discounted subtotal", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(50),
    };
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      region: "US-CA",
    });
    cart.add(productA, 1); // subtotal 1000, discount 200, discountedSubtotal 800
    cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
  });

  it("shipping is computed against lines and discounted subtotal", () => {
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      shippingCalculator: mockShipping,
    });
    cart.add(productA, 2); // subtotal 2000, discount 300, discounted 1700
    const t = cart.totals();
    expect(t.shippingCents).toBe(599);
    expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      1700,
    );
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(90),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      shippingCalculator: mockShipping,
    });
    cart.add(productA, 1); // subtotal 1000, discount 100, discounted 900
    const t = cart.totals();
    // total = 900 + 90 + 500 = 1490
    expect(t.totalCents).toBe(1490);
  });

  it("defaults to US region", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(productA, 1);
    cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });

  it("negative tax from calculator is clamped to 0", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("negative shipping from calculator is clamped to 0", () => {
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator: mockShipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

