describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("uses refreshed prices from priceFetcher", async () => {
      const cart = new Cart();
      cart.add(productA, 2); // original 1000 each

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const result = await cart.checkout({ priceFetcher });
      // refreshed: 1500 * 2 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("throws RangeError if fetcher returns invalid price", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-5),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("throws RangeError if fetcher returns non-integer price", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(10.5),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("propagates fetcher rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("network down")),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("network down");
    });
  });

  describe("inventory checking", () => {
    it("passes when all items are available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError on denial (available: false)", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 3,
          reason: "low stock",
        }),
      };

      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(3);
        expect(err.message).toBe("low stock");
      }
    });

    it("throws InventoryError for partial-stock denial (availableQuantity < requested)", async () => {
      const cart = new Cart();
      cart.add(productA, 10);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    });

    it("does not throw when availableQuantity >= requested", async () => {
      const cart = new Cart();
      cart.add(productA, 3);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 5,
        }),
      };

      await expect(cart.checkout({ inventoryChecker })).resolves.toBeDefined();
    });

    it("checks first item that fails (first denial wins)", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
      };

      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.productId).toBe("b");
        expect(err.message).toBe("discontinued");
      }
    });

    it("generates default message when no reason provided", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };

      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.message).toContain("insufficient stock");
        expect(err.available).toBeUndefined();
      }
    });
  });

  describe("async tax provider", () => {
    it("uses async tax provider for tax calculation", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(productA, 1); // subtotal 1000

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // tax = 10% of 1000 = 100
      expect(result.totals.taxCents).toBe(100);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("async tax applies to discounted subtotal", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        region: "US",
      });
      cart.add(productA, 1); // subtotal 1000, discount 200, discounted 800

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // tax = 10% of 800 = 80
      expect(result.totals.taxCents).toBe(80);
    });

    it("propagates async tax provider error", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("service unavailable")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("service unavailable");
    });

    it("throws RangeError for invalid async tax rate", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(2.0),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(RangeError);
    });
  });

  describe("full pipeline composition", () => {
    it("combines price refresh + inventory + async tax + discount + shipping", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "FR",
      });
      cart.add(productA, 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(2000),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.2),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // refreshed subtotal: 2000 * 2 = 4000
      expect(result.totals.subtotalCents).toBe(4000);
      // discount: 10% of 4000 = 400
      expect(result.totals.discountCents).toBe(400);
      // discountedSubtotal = 3600
      // tax: 20% of 3600 = 720
      expect(result.totals.taxCents).toBe(720);
      // shipping: flat 500 (cart has items, discounted subtotal 3600 no free-over)
      expect(result.totals.shippingCents).toBe(500);
      // total: 3600 + 720 + 500 = 4820
      expect(result.totals.totalCents).toBe(4820);

      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].product.unitPriceCents).toBe(2000);
    });

    it("checkout without collaborators uses sync pipeline", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.totalCents).toBe(1000);
    });

    it("returns refreshed lines in result", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn()
          .mockResolvedValueOnce(1100)
          .mockResolvedValueOnce(2200),
      };

      const result = await cart.checkout({ priceFetcher });
      expect(result.lines).toHaveLength(2);
      const prices = result.lines.map((l) => l.product.unitPriceCents).sort();
      expect(prices).toEqual([1100, 2200]);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { InventoryError, refreshPrices } from "../src/inventory.ts";
import type { PriceFetcher } from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("InventoryError", () => {
  it("has correct name", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err.name).toBe("InventoryError");
  });

  it("stores productId, requested, and available", () => {
    const err = new InventoryError("msg", "prod-1", 10, 3);
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(10);
    expect(err.available).toBe(3);
  });

  it("stores undefined available", () => {
    const err = new InventoryError("msg", "prod-1", 5, undefined);
    expect(err.available).toBeUndefined();
  });

  it("extends Error", () => {
    const err = new InventoryError("msg", "prod-1", 1, 0);
    expect(err).toBeInstanceOf(Error);
  });

  it("message is set correctly", () => {
    const err = new InventoryError("out of stock!", "p", 1, 0);
    expect(err.message).toBe("out of stock!");
  });
});

describe("refreshPrices", () => {
  const lines: CartLine[] = [
    { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 2 },
    { product: { id: "b", name: "B", unitPriceCents: 200 }, quantity: 1 },
  ];

  it("returns lines with updated prices", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(150)
        .mockResolvedValueOnce(250),
    };

    const result = await refreshPrices(lines, fetcher);
    expect(result).toHaveLength(2);
    expect(result[0].product.unitPriceCents).toBe(150);
    expect(result[0].quantity).toBe(2);
    expect(result[1].product.unitPriceCents).toBe(250);
    expect(result[1].quantity).toBe(1);
  });

  it("preserves other product fields", async () => {
    const lineWithWeight: CartLine[] = [
      { product: { id: "x", name: "X", unitPriceCents: 100, weightGrams: 500, currency: "EUR" }, quantity: 1 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(200),
    };

    const result = await refreshPrices(lineWithWeight, fetcher);
    expect(result[0].product.weightGrams).toBe(500);
    expect(result[0].product.currency).toBe("EUR");
    expect(result[0].product.name).toBe("X");
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };

    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(9.99),
    };

    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(NaN),
    };

    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("timeout")),
    };

    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("timeout");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };

    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });

  it("calls fetcher with correct product IDs", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(100),
    };

    await refreshPrices(lines, fetcher);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("b");
    expect(fetcher.fetchPriceCents).toHaveBeenCalledTimes(2);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for a positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects percent < 0", () => {
      expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects percent > 100", () => {
      expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
    });

    it("rejects NaN", () => {
      expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
    });

    it("rejects Infinity", () => {
      expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
    });

    it("accepts 100", () => {
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 = 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down to nearest cent", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 33% of 100 = 33.0 exactly
      expect(policy.computeDiscountCents(100)).toBe(33);
      // 33% of 101 = 33.33 → floor → 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-1000)).toBe(0);
    });

    it("100% discount equals subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(9999)).toBe(9999);
    });

    it("0% discount equals 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(50000)).toBe(0);
    });

    it("handles very large subtotal", () => {
      const policy = new PercentageDiscountPolicy(25);
      expect(policy.computeDiscountCents(1_000_000_00)).toBe(25_000_000);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal is greater", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when discount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exactly subtotal when equal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies against original subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
        new FixedAmountDiscountPolicy(500), // min(500, 10000) = 500
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("returns 0 for zero subtotal", () => {
      const policies = [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policies = [new PercentageDiscountPolicy(10)];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const policies = [
        new PercentageDiscountPolicy(80), // 80% of 1000 = 800
        new FixedAmountDiscountPolicy(500), // min(500, 1000) = 500
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      // 800 + 500 = 1300 > 1000 — but composite just sums, caller clamps
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });

    it("defaults to sum mode when not specified", () => {
      const policies = [
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ];
      const composite = new CompositeDiscountPolicy(policies);
      // sum: 10% of 5000 = 500, fixed = 200, total = 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, remaining 9000
        new FixedAmountDiscountPolicy(500), // min(500, 9000) = 500, remaining 8500
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("ordering matters in chain mode", () => {
      const policiesA = [
        new FixedAmountDiscountPolicy(500), // 500 off 10000, remaining 9500
        new PercentageDiscountPolicy(10), // 10% of 9500 = 950
      ];
      const policiesB = [
        new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, remaining 9000
        new FixedAmountDiscountPolicy(500), // 500 off 9000
      ];
      const compositeA = new CompositeDiscountPolicy(policiesA, "chain");
      const compositeB = new CompositeDiscountPolicy(policiesB, "chain");
      expect(compositeA.computeDiscountCents(10000)).toBe(1450);
      expect(compositeB.computeDiscountCents(10000)).toBe(1500);
    });

    it("stops accumulating when remaining reaches 0", () => {
      const policies = [
        new PercentageDiscountPolicy(100), // 100% of 1000 = 1000, remaining 0
        new FixedAmountDiscountPolicy(500), // min(500, 0) = 0 — subtotal <= 0
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policies = [new PercentageDiscountPolicy(50)];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
