describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies against original subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
        new FixedAmountDiscountPolicy(500), // min(500, 10000) = 500
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("returns 0 for zero subtotal", () => {
      const policies = [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policies = [new PercentageDiscountPolicy(10)];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const policies = [
        new PercentageDiscountPolicy(80), // 80% of 1000 = 800
        new FixedAmountDiscountPolicy(500), // min(500, 1000) = 500
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      // 800 + 500 = 1300 > 1000 — but composite just sums, caller clamps
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });

    it("defaults to sum mode when not specified", () => {
      const policies = [
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ];
      const composite = new CompositeDiscountPolicy(policies);
      // sum: 10% of 5000 = 500, fixed = 200, total = 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, remaining 9000
        new FixedAmountDiscountPolicy(500), // min(500, 9000) = 500, remaining 8500
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("ordering matters in chain mode", () => {
      const policiesA = [
        new FixedAmountDiscountPolicy(500), // 500 off 10000, remaining 9500
        new PercentageDiscountPolicy(10), // 10% of 9500 = 950
      ];
      const policiesB = [
        new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, remaining 9000
        new FixedAmountDiscountPolicy(500), // 500 off 9000
      ];
      const compositeA = new CompositeDiscountPolicy(policiesA, "chain");
      const compositeB = new CompositeDiscountPolicy(policiesB, "chain");
      expect(compositeA.computeDiscountCents(10000)).toBe(1450);
      expect(compositeB.computeDiscountCents(10000)).toBe(1500);
    });

    it("stops accumulating when remaining reaches 0", () => {
      const policies = [
        new PercentageDiscountPolicy(100), // 100% of 1000 = 1000, remaining 0
        new FixedAmountDiscountPolicy(500), // min(500, 0) = 0 — subtotal <= 0
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policies = [new PercentageDiscountPolicy(50)];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});
