      expect(result.totals.taxCents).toBe(720);
      // shipping: flat 500 (cart has items, discounted subtotal 3600 no free-over)
      expect(result.totals.shippingCents).toBe(500);
      // total: 3600 + 720 + 500 = 4820
      expect(result.totals.totalCents).toBe(4820);

